use kino_core::color::delivery::inspect;
#[test]fn delivery_bad_paths(){for p in ["","-evil","https://example.invalid/a.mp4","/tmp","/tmp/no-kino-source-invalid.mp4"]{assert!(inspect(p).is_err());}}
#[test]fn declared_delivery_tags(){let p=std::env::temp_dir().join(format!("kino-delivery-{}.mp4",std::process::id()));assert!(std::process::Command::new("ffmpeg").args(["-v","error","-y","-f","lavfi","-i","color=c=red:s=32x32:r=25:d=0.1","-c:v","libx264","-color_primaries","bt709","-color_trc","iec61966-2-1","-colorspace","bt709","-color_range","tv",p.to_str().unwrap()]).status().unwrap().success());let v=inspect(p.to_str().unwrap()).unwrap();assert_eq!(v["streams"][0]["color_transfer"],"iec61966-2-1");assert_eq!(v["streams"][0]["width"],32);assert!(v["tag_gaps"][0]["absent_or_unspecified_color_fields"].as_array().unwrap().is_empty());std::fs::remove_file(p).unwrap();}
